const fs = require('fs');
const path = require('path');

const brainDir = 'C:/Users/admin/.gemini/antigravity/brain';
const convDirs = fs.readdirSync(brainDir);

for (const conv of convDirs) {
  const tFull = path.join(brainDir, conv, '.system_generated/logs/transcript_full.jsonl');
  const tShort = path.join(brainDir, conv, '.system_generated/logs/transcript.jsonl');
  const p = fs.existsSync(tFull) ? tFull : (fs.existsSync(tShort) ? tShort : null);
  if (!p) continue;

  // Read file and search for 685: or 690:
  const content = fs.readFileSync(p, 'utf8');
  if (content.includes('685:') && content.includes('Sidebar.jsx')) {
    console.log(`Found in conv: ${conv}`);
    // Extract the tool call output
    const lines = content.split('\n');
    for (const l of lines) {
      if (l.includes('685:') && l.includes('Sidebar.jsx')) {
        try {
          const parsed = JSON.parse(l);
          console.log('Step content sample:', JSON.stringify(parsed).slice(0, 500));
          // Save full step
          fs.writeFileSync('c:/Users/admin/Downloads/nib_hr/scratch/found_missing_step.json', l, 'utf8');
          console.log('Saved to found_missing_step.json');
        } catch(e) {
          console.log('Error parsing JSON:', e.message);
        }
        break;
      }
    }
  }
}
